/**
 * The default maximum length (in UTF-16 code units) for a stringified
 * telemetry attribute value before it is truncated.
 */
const DEFAULT_TELEMETRY_MAX_LENGTH = 10_000;

/**
 * Safely prepares an arbitrary value for use as an OpenTelemetry attribute,
 * truncating long strings at grapheme-cluster boundaries so multi-byte unicode
 * characters are never split in half.
 *
 * - Strings are returned unchanged when within `maxLength`, otherwise truncated
 *   with a `...[TRUNCATED: original length N]` suffix.
 * - Objects are `JSON.stringify`-ed and then truncated using the same logic.
 * - Numbers and booleans are returned unchanged.
 * - `undefined`, functions, and symbols return `undefined`.
 *
 * @param value The value to prepare.
 * @param maxLength The maximum string length before truncation.
 * @returns An `AttributeValue`, or `undefined` if the value cannot be
 *   represented as a telemetry attribute.
 */
export function truncateForTelemetry(
  value: unknown,
  maxLength: number = DEFAULT_TELEMETRY_MAX_LENGTH,
): AttributeValue | undefined {
  switch (typeof value) {
    case 'undefined':
    case 'function':
    case 'symbol':
      return undefined;
    case 'number':
    case 'boolean':
      return value;
    case 'string':
      return truncateString(value, maxLength);
    default: {
      // Objects (and anything else, e.g. bigint) are serialized to JSON.
      let serialized: string | undefined;
      try {
        serialized = JSON.stringify(value);
      } catch {
        return undefined;
      }
      if (serialized === undefined) {
        return undefined;
      }
      return truncateString(serialized, maxLength);
    }
  }
}

/**
 * Truncates a string at grapheme-cluster boundaries when it exceeds
 * `maxLength`, appending a suffix noting the original length.
 */
function truncateString(value: string, maxLength: number): string {
  if (value.length <= maxLength) {
    return value;
  }

  const segmenter = new Intl.Segmenter(undefined, { granularity: 'grapheme' });
  let truncated = '';
  for (const { segment } of segmenter.segment(value)) {
    if (truncated.length + segment.length > maxLength) {
      break;
    }
    truncated += segment;
  }

  return `${truncated}...[TRUNCATED: original length ${value.length}]`;
