          }
        }
        if (logPrompts && meta.output !== undefined) {
          const output = truncateForTelemetry(meta.output);
          if (output !== undefined) {
            span.setAttribute(GEN_AI_OUTPUT_MESSAGES, output);
          }
        }
        for (const [key, value] of Object.entries(meta.attributes)) {
          span.setAttribute(key, value);
        }
        if (meta.error) {
          span.setStatus({
            code: SpanStatusCode.ERROR,
            message: getErrorMessage(meta.error),
          });
          if (meta.error instanceof Error) {
            span.recordException(meta.error);
          }
        } else {
          span.setStatus({ code: SpanStatusCode.OK });
        }
      } catch (e) {
        // Log the error but don't rethrow, to ensure span.end() is called.
        diag.error('Error setting span attributes in endSpan', e);
        span.setStatus({
          code: SpanStatusCode.ERROR,
          message: `Error in endSpan: ${getErrorMessage(e)}`,
        });
      } finally {
        span.end();
      }
    };

    let result: R;
    try {
      result = await fn({ metadata: meta });
    } catch (e) {
      meta.error = e;
      endSpan();
      throw e;
