}

/**
 * Wraps an async iterable so the span is ended once iteration finishes, is
 * abandoned early, or throws. Errors are recorded on the span metadata and
 * re-thrown after the span is ended.
 */
async function* wrapAsyncIterable<T>(
  iterable: AsyncIterable<T>,
  meta: SpanMetadata,
  endSpan: () => void,
): AsyncGenerator<T> {
  try {
    for await (const item of iterable) {
      yield item;
    }
  } catch (e) {
    meta.error = e;
    throw e;
  } finally {
    endSpan();
  }
